document.getElementById('request-id').value = newRequestId();
loadCatalog();
refreshBudget();
refreshHistory();

function localInputToIso(value) {
  if (!value) return '';
  return new Date(value).toISOString();
}

document.getElementById('export-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const message = document.getElementById('export-message');
  const button = document.getElementById('export-button');
  const params = new URLSearchParams();
  params.set('format', document.getElementById('export-format').value);
  const datasetId = document.getElementById('export-dataset').value;
  if (datasetId) params.set('dataset_id', datasetId);
  const requestId = document.getElementById('export-request-id').value.trim();
  if (requestId) params.set('request_id', requestId);
  const fromIso = localInputToIso(document.getElementById('export-from').value);
  const toIso = localInputToIso(document.getElementById('export-to').value);
  if (fromIso) params.set('from', fromIso);
  if (toIso) params.set('to', toIso);
  const limitRaw = document.getElementById('export-limit').value;
  const limit = Number.parseInt(limitRaw, 10);
  if (limitRaw === '' || !Number.isInteger(limit) || limit < 1 || limit > 100) {
    message.className = 'error';
    message.textContent = '导出失败：limit 必须是 1–100 的整数。';
    return;
  }
  params.set('limit', String(limit));
  if (fromIso && toIso && new Date(fromIso) >= new Date(toIso)) {
    message.className = 'error';
    message.textContent = '导出失败：起始时间必须早于结束时间。';
    return;
  }
  message.className = '';
  message.textContent = '';
  button.disabled = true;
  try {
    const response = await fetch(`/api/releases/export?${params.toString()}`);
    if (!response.ok) {
      const data = await response.json().catch(() => null);
      message.className = 'error';
      message.textContent = `导出失败：${formatError(data, response.status)}`;
      return;
    }
    const format = params.get('format');
    const text = await response.text();
    let empty = false;
    if (format === 'json') {
      let parsed;
      try { parsed = JSON.parse(text); } catch (_) { parsed = null; }
      empty = Array.isArray(parsed) && parsed.length === 0;
    } else {
      empty = text.trim().split(/\r?\n/).length <= 1;
    }
    const blob = new Blob([text], {
      type: format === 'json' ? 'application/json' : 'text/csv;charset=utf-8',
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `releases-export.${format}`;
    document.body.append(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    message.className = empty ? '' : 'success';
    message.textContent = empty
      ? '没有匹配的发布记录，已下载空结果文件。'
      : '导出文件已开始下载。';
  } catch (error) {
    message.className = 'error';
    message.textContent = `导出失败：${error.message}`;
  } finally {
    button.disabled = false;
  }
});
